Local Ltac fast_eassumption :=
  first [ lazymatch goal with
          | |- rw_cells _ ?M ?A _ => assert_fails (is_evar M); match goal with H : rw_cells _ M A _ |- _ => exact H end
          | |- ro_cells _ _ ?A _ => match goal with H : ro_cells _ _ A _ |- _ => exact H end
          | |- bytes_at _ ?M ?A _ => assert_fails (is_evar M); match goal with H : bytes_at _ M A _ |- _ => exact H end
          | |- u8arr _ ?M ?A _ => assert_fails (is_evar M); match goal with H : u8arr _ M A _ |- _ => exact H end
          end
        | eassumption ].
(* [comment removed for export] *)
Local Ltac fit_zsizes :=
  repeat match goal with
  | |- context [Z.of_nat (cells_size ?cs)] =>
      let v := eval cbn [cells_size csize length Nat.add Z.of_nat Pos.of_succ_nat Pos.succ] in (Z.of_nat (cells_size cs)) in
      lazymatch v with Z0 => idtac | Zpos _ => idtac end;     (* [comment removed for export] *)
      change (Z.of_nat (cells_size cs)) with v
  end.
(* [comment removed for export] *)
Local Ltac dj_lia ::=
  first [ let a := dj_subject in progress (dj_reveal_for a); lia
        | lia
        | match goal with K : hideL _ |- _ => unfold hideL in K; lia end ].
Lemma rw_cells_CB0_intro : forall m A, 0 <= A <= 2^64 -> rw_cells asegs m A [CB 0 []].
Proof.
  intros m A HA. split; [split|].
  - cbn. split; [reflexivity| exact I].
  - split; [lia|]. split; [cbn; lia|]. intros i Hi. cbn in Hi. lia.
  - split; [lia|]. split; [cbn; lia|]. intros i Hi. cbn in Hi. lia.
Qed.

(* [comment removed for export] *)
Lemma tokit_after_size : forall r a b, cells_size (tokit_cells_after r a b) = 40%nat.
Proof. intros [| |k l] a b; reflexivity. Qed.
Lemma tokit_after_wf : forall r a b, cells_wf (tokit_cells_after r a b).
Proof. intros [| |k l] a b; cbn; repeat split. Qed.
Lemma tokit_after_sized : forall m A r a b,
  rw_cells asegs m A (tokit_cells_after r a b) -> rw_cells asegs m A [CB 40 (cells_bytes (tokit_cells_after r a b))].
Proof.
  intros m A r a b C. rewrite <- (app_nil_r (tokit_cells_after r a b)) in C.
  apply (rw_cells_merge asegs m A [] (tokit_cells_after r a b) []) in C. cbn [app] in C. rewrite tokit_after_size in C. exact C.
Qed.
Lemma tokit_after_unsized : forall m A r a b,
  rw_cells asegs m A [CB 40 (cells_bytes (tokit_cells_after r a b))] -> rw_cells asegs m A (tokit_cells_after r a b).
Proof.
  intros m A r a b C. eapply rw_cells_reshape; [exact C | apply tokit_after_wf | cbn [cells_bytes cbytes]; rewrite app_nil_r; reflexivity].
Qed.

