    (F : bvmap 5 word) fc (m m1 : mem) (spa : Z) (gsz : nat) (lj gj : list byte),
  rw_cells asegs m1 spa [CB 120 lj] ->
  rw_cells asegs m1 (spa + 120) [CB gsz gj] ->
  rw_cells asegs m1 (bv_unsigned sp + -104) [C8 s11; C8 s10; C8 s9; C8 s8; C8 s7; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra] ->
